oxy_webhelp_navlinks = {"api_playground-d39536e64138":{"topics":[{"title":"Accessing API Playground","shortdesc":"<p class=\"shortdesc\">Access API Playground in your <span class=\"ph\">RSC<\/span> domain by authenticating         to <span class=\"ph\">RSC<\/span> using your account credentials. With access to API Playground, you         can explore the Rubrik GraphQL schema and perform data security operations using GraphQL         queries and mutations.<\/p>","href":"gql\/accessing_api_playground.html","attributes":{"data-id":"accessing_api_playground"},"menu":{"hasChildren":false},"tocID":"accessing_api_playground-d39536e64155","topics":[]},{"title":"Non-persistence of service account sessions in API Playground","shortdesc":"<p class=\"shortdesc\">When you use a service account to run GraphQL API operations in API Playground, for         security reasons, API Playground does not persist the service account credentials and         renders the service account access token invalid when the service account session ends or         becomes inactive.<\/p>","href":"gql\/sa_session_non_persistence_api_playground.html","attributes":{"data-id":"sa_session_non_persistence_api_playground"},"menu":{"hasChildren":false},"tocID":"sa_session_non_persistence_api_playground-d39536e64172","topics":[]},{"title":"Using a service account to run GraphQL APIs","shortdesc":"<p class=\"shortdesc\">In API Playground, run GraphQL queries and mutations with a service account to test         and validate the service account's use in automation scripts.<\/p>","href":"gql\/using_sa_to_run_gql.html","attributes":{"data-id":"using_sa_to_run_gql"},"menu":{"hasChildren":false},"tocID":"using_sa_to_run_gql-d39536e64183","topics":[]},{"title":"API Playground user interface","shortdesc":"<p class=\"shortdesc\">The API Playground user interface in <span class=\"ph\">RSC<\/span> uses the GraphiQL integrated         development environment (IDE) to run Rubrik GraphQL operations.<\/p>","href":"gql\/api_playground_ui.html","attributes":{"data-id":"api_playground_ui"},"menu":{"hasChildren":false},"tocID":"api_playground_ui-d39536e64194","topics":[]},{"title":"Accepted values for generateK8sManifest distribution and transport fields","shortdesc":"<p class=\"shortdesc\">The <span class=\"keyword parmname\">distribution<\/span> and <span class=\"keyword parmname\">transport<\/span> fields on         the <code class=\"ph codeph\">generateK8sManifest<\/code> GraphQL mutation accept the values in the         following tables.<\/p>","href":"gql\/k8s_manifest_config_values.html","attributes":{"data-id":"k8s_manifest_config_values"},"menu":{"hasChildren":false},"tocID":"k8s_manifest_config_values-d39536e64208","topics":[]}]}};